"""Google OAuth2 helpers (§1F, authlib).

Design notes:
  * Config is read at CALL time (``get_settings()``), so tests can set
    GOOGLE_OAUTH_CLIENT_ID/SECRET via env without import-order issues, and the
    endpoints degrade cleanly (503) when unconfigured.
  * ``exchange_code`` is a MODULE-LEVEL function that the routes call via
    attribute access (``oauth_handler.exchange_code(...)``) precisely so tests
    can monkeypatch it and never hit Google. The real implementation uses
    authlib's AsyncOAuth2Client (token endpoint + OIDC userinfo).
  * The ``state`` parameter is generated by the login endpoint, stored in Redis
    (``oauth_state:{state}``, TTL 600, single-use) and validated on callback —
    CSRF protection for the OAuth flow (§1F/§1H).
"""
from __future__ import annotations

import secrets
from dataclasses import dataclass
from typing import Optional
from urllib.parse import urlencode

import structlog

from ..config import get_settings

logger = structlog.get_logger(__name__)

GOOGLE_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth"
GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token"
GOOGLE_USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo"

OAUTH_STATE_TTL = 600  # 10 minutes to complete the consent screen
_SCOPES = "openid email profile"


@dataclass
class GoogleProfile:
    """The subset of the Google OIDC profile the app uses (§1F step 2)."""

    sub: str            # Google's stable user id
    email: str
    name: str
    picture: Optional[str] = None
    email_verified: bool = True


def is_configured() -> bool:
    s = get_settings()
    return bool(s.GOOGLE_OAUTH_CLIENT_ID and s.GOOGLE_OAUTH_CLIENT_SECRET)


def generate_state() -> str:
    return secrets.token_urlsafe(32)


def build_authorize_url(state: str, redirect_uri: str) -> str:
    """The Google consent-screen URL the login endpoint redirects to."""
    s = get_settings()
    params = {
        "client_id": s.GOOGLE_OAUTH_CLIENT_ID,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": _SCOPES,
        "state": state,
        "access_type": "online",
        "prompt": "select_account",
    }
    return f"{GOOGLE_AUTHORIZE_URL}?{urlencode(params)}"


class OAuthExchangeError(Exception):
    """Raised when the code->token->profile exchange fails."""


async def exchange_code(code: str, redirect_uri: str) -> GoogleProfile:
    """Exchange an authorization code for the user's Google profile.

    Tests monkeypatch THIS function (``backend.auth.oauth_handler.exchange_code``)
    so no real Google call is ever made in the suite.
    """
    from authlib.integrations.httpx_client import AsyncOAuth2Client

    s = get_settings()
    client = AsyncOAuth2Client(
        client_id=s.GOOGLE_OAUTH_CLIENT_ID,
        client_secret=s.GOOGLE_OAUTH_CLIENT_SECRET,
        redirect_uri=redirect_uri,
    )
    try:
        await client.fetch_token(GOOGLE_TOKEN_URL, code=code)
        resp = await client.get(GOOGLE_USERINFO_URL)
        resp.raise_for_status()
        info = resp.json()
    except Exception as exc:  # noqa: BLE001
        logger.warning("oauth_exchange_failed", error=str(exc))
        raise OAuthExchangeError("Google token exchange failed") from exc
    finally:
        await client.aclose()

    try:
        return GoogleProfile(
            sub=str(info["sub"]),
            email=info["email"],
            name=info.get("name") or info["email"].split("@", 1)[0],
            picture=info.get("picture"),
            email_verified=bool(info.get("email_verified", True)),
        )
    except KeyError as exc:
        raise OAuthExchangeError(f"Google profile missing field: {exc}") from exc
